// #67d710 (№31) «Android - במסך «המסע שלי» הטקסט «דרגה 1 מתוך 10» נחתך מחוץ למסך בזום 200%» — עבר QA 09.11.
//   מה רצוי: «בזום 200% כל הטקסט נשאר בתוך המסך (נשבר לשורה נוספת לפי הצורך), ו«דרגה 1 מתוך 10» נקרא במלואו».
//   В «מה קיים» также: «הסמל השמאלי בכותרת העליונה נחתך בקצה».
// Факт 09.11 (Pixel 6, wm density 840, аккаунт «QA reg 0311»): «דרגה 1 מתוך 10» отдельной строкой в экране; значок шапки в экране (f03c00a).
// Номер דרגה зависит от аккаунта → «דרגה N מתוך 10». Кейс: .qa/tests/zoom-200/Z2-05-journey-level.md. Только просмотр.
import { driver, expect } from '@wdio/globals';
import { goTab } from '../../helpers/nav.ts';
import { goHome, nodes } from '../_lib/readiness-1910.ts';
import { skipWith } from '../_lib/app-0710.ts';
import { zoomOn, zoomOff, textNode, textNodeMatching, insideScreenX, saveShot } from '../_lib/app-0911.ts';

const LEVEL = /^דרגה \d+ מתוך 10$/;

describe('09.11 — зум 200% (Android): «המסע שלי» — דרגה в экране (#67d710)', () => {
  before(function () { if (!driver.isAndroid) skipWith(this, 'зум через wm density — только Android'); });
  after(async () => { if (driver.isAndroid) await zoomOff(); });

  it('Z2-05 При wm density 840 «דרגה N מתוך 10» — отдельный текст целиком в экране; элементы шапки «המסע שלי» не выходят за края #67d710 @android @prod-safe @manual-check', async () => {
    await goHome();
    await zoomOn();
    await goTab('המסע שלי');
    await textNode('המסע שלי');

    // 1. «דרגה N מתוך 10» — свой текстовый элемент (не хвост строки «… · דרגה …»), рамка внутри экрана.
    const level = await textNodeMatching(LEVEL);
    await saveShot('q30-journey-level.png');
    console.log(`[Q-30] «${level.label}»: x${level.x} w${level.w}`);
    expect(await insideScreenX(level)).toBe(true);

    // 2. Шапка (верхние 15% экрана): все элементы с подписью — в экране по ширине (значок слева не обрезан).
    const { height } = await driver.getWindowSize();
    const header = (await nodes()).filter((n) => n.visible && n.w > 0 && n.y < height * 0.15 && n.y > 0);
    expect(header.length).toBeGreaterThan(0);
    for (const n of header) {
      console.log(`[Q-30] шапка «${n.label.slice(0, 30)}» x${n.x}..${n.x + n.w}`);
      expect(await insideScreenX(n)).toBe(true);
    }
    // Глазами по q30-journey-level.png: «דרגה N מתוך 10» читается целиком, значок шапки виден полностью.
  });
});
